import numpy as np

def hrp_weights(cov, corr):
    n = cov.shape[0]
    dist = np.sqrt(0.5 * (1 - corr))

    # single-linkage agglomerative clustering
    members = {i: [i] for i in range(n)}
    active = list(range(n))
    next_id = n
    merges = {}
    while len(active) > 1:
        best, best_d = None, None
        for a_idx in range(len(active)):
            for b_idx in range(a_idx + 1, len(active)):
                a, b = active[a_idx], active[b_idx]
                d = min(dist[i, j] for i in members[a] for j in members[b])
                if best_d is None or d < best_d:
                    best_d, best = d, (a, b)
        a, b = best
        members[next_id] = members[a] + members[b]
        merges[next_id] = (a, b)
        active.remove(a); active.remove(b); active.append(next_id)
        next_id += 1

    def leaf_order(cid):
        if cid < n:
            return [cid]
        a, b = merges[cid]
        return leaf_order(a) + leaf_order(b)

    order = leaf_order(next_id - 1)

    # recursive bisection
    def cluster_var(items):
        sub = cov[np.ix_(items, items)]
        ivp = 1 / np.diag(sub)
        ivp = ivp / ivp.sum()
        return ivp @ sub @ ivp

    weights = {i: 1.0 for i in order}
    clusters = [order]
    while True:
        new_clusters = []
        for c in clusters:
            if len(c) > 1:
                mid = len(c) // 2
                new_clusters.append(c[:mid])
                new_clusters.append(c[mid:])
        if not new_clusters:
            break
        for i in range(0, len(new_clusters), 2):
            c0, c1 = new_clusters[i], new_clusters[i + 1]
            v0, v1 = cluster_var(c0), cluster_var(c1)
            alpha = 1 - v0 / (v0 + v1)
            for a in c0: weights[a] *= alpha
            for a in c1: weights[a] *= (1 - alpha)
        clusters = new_clusters

    w = np.array([weights[i] for i in range(n)])
    return w / w.sum()

# Replace with your own volatility and correlation estimates
vol = np.array([0.14, 0.18, 0.17, 0.05, 0.12])
corr = np.array([
    [1.00, 0.85, 0.75, -0.08, 0.05],
    [0.85, 1.00, 0.55, -0.05, 0.03],
    [0.75, 0.55, 1.00, -0.05, 0.02],
    [-0.08, -0.05, -0.05, 1.00, 0.00],
    [0.05, 0.03, 0.02, 0.00, 1.00],
])
cov = np.outer(vol, vol) * corr
print('HRP weights:', np.round(hrp_weights(cov, corr) * 100, 2))
